package cli

import (
	"fmt"
	"time"

	"github.com/mvanhorn/printing-press-library/library/commerce/flipkart/internal/cliutil"
	"github.com/mvanhorn/printing-press-library/library/commerce/flipkart/internal/store"

	"github.com/spf13/cobra"
)

func newWatchCheckCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:         "check",
		Short:       "Re-fetch current prices for every watched product and flag any at or below threshold.",
		Example:     "  flipkart-pp-cli watch check",
		Annotations: map[string]string{"mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			db, err := store.OpenWithContext(cmd.Context(), defaultDBPath("flipkart-pp-cli"))
			if err != nil {
				return fmt.Errorf("opening local database: %w", err)
			}
			defer db.Close()
			if err := db.EnsureFlipkartSchema(); err != nil {
				return err
			}

			watches, err := db.ListFlipkartWatches()
			if err != nil {
				return fmt.Errorf("listing watches: %w", err)
			}
			if len(watches) == 0 {
				return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
					"status":  "no_watches",
					"message": "no watches configured yet. Run 'watch add <product-url> --threshold <price>' first.",
				}, flags)
			}

			limit := len(watches)
			if cliutil.IsDogfoodEnv() && limit > 1 {
				limit = 1
			}

			if dryRunOK(flags) {
				urls := make([]string, 0, limit)
				for _, w := range watches[:limit] {
					urls = append(urls, w.URL)
				}
				fmt.Fprintf(cmd.ErrOrStderr(), "would re-fetch %d/%d watched product(s):\n", limit, len(watches))
				for _, u := range urls {
					fmt.Fprintf(cmd.ErrOrStderr(), "  %s\n", u)
				}
				fmt.Fprintln(cmd.ErrOrStderr(), "(dry run - no request sent)")
				return nil
			}

			c, err := flags.newClient()
			if err != nil {
				return err
			}

			now := time.Now()
			results := make([]map[string]any, 0, limit)
			for _, w := range watches[:limit] {
				p, err := fetchProductDetail(cmd.Context(), c.HTTPClient, w.URL)
				if err != nil {
					results = append(results, map[string]any{
						"product_id": w.ProductID,
						"url":        w.URL,
						"error":      err.Error(),
					})
					continue
				}
				if err := db.InsertFlipkartPriceHistory(w.ProductID, p.Price, now); err != nil {
					return fmt.Errorf("recording price history for %s: %w", w.ProductID, err)
				}
				if err := db.UpdateFlipkartWatchLastChecked(w.ProductID, now); err != nil {
					return fmt.Errorf("updating last_checked_at for %s: %w", w.ProductID, err)
				}
				atOrBelow := w.Threshold > 0 && p.Price <= w.Threshold
				results = append(results, map[string]any{
					"product_id":            w.ProductID,
					"url":                   w.URL,
					"title":                 p.Title,
					"price":                 p.Price,
					"threshold":             w.Threshold,
					"at_or_below_threshold": atOrBelow,
				})
			}

			if cliutil.IsDogfoodEnv() && limit < len(watches) {
				fmt.Fprintf(cmd.ErrOrStderr(), "note: dogfood mode — checked %d/%d watched products to stay within the per-command timeout.\n", limit, len(watches))
			}

			return printJSONFiltered(cmd.OutOrStdout(), results, flags)
		},
	}
	return cmd
}
